);

    // ============================================================
    // Synchronous reset synchronizers
    // ============================================================
    reg [2:0] s_rst_sync;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            s_rst_sync <= 3'b111;
        else
            s_rst_sync <= {s_rst_sync[1:0], 1'b0};
    end
    wire s_rst_synced = s_rst_sync[2];

    reg [2:0] m_rst_sync;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            m_rst_sync <= 3'b111;
        else
            m_rst_sync <= {m_rst_sync[1:0], 1'b0};
    end
    wire m_rst_synced = m_rst_sync[2];

    // ============================================================
    // Handshake CDC primitives
    // ============================================================

    // Request: S-domain -> M-domain
    // req_reg is in S-domain, req_sync in M-domain
    reg        req_reg;
    reg [2:0]  req_sync;
    wire       req_synced = req_sync[2];

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            req_reg <= 1'b0;
        else
            req_reg <= req_synced; // pulse when M-domain acknowledges
    end

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            req_sync <= 3'b000;
        else
            req_sync <= {req_sync[1:0], req_reg};
    end

    // Response: M-domain -> S-domain
    // resp_reg is in M-domain, resp_sync in S-domain
    reg        resp_reg;
    reg [2:0]  resp_sync;
    wire       resp_synced = resp_sync[2];

    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            resp_reg <= 1'b0;
        else
            resp_reg <= resp_synced; // pulse when S-domain acknowledges
    end

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            resp_sync <= 3'b000;
        else
            resp_sync <= {resp_sync[1:0], resp_reg};
    end

