    // S-domain: Slave interface logic
    // ============================================================

    // Write address channel
    reg        s_aw_pending;
    reg [ADDR_WIDTH-1:0] s_aw_addr_reg;
    reg [2:0]  s_aw_prot_reg;

    // Write data channel
    reg        s_w_pending;
    reg [DATA_WIDTH-1:0] s_w_data_reg;
    reg [STRB_WIDTH-1:0] s_w_strb_reg;

    // Read address channel
    reg        s_ar_pending;
    reg [ADDR_WIDTH-1:0] s_ar_addr_reg;
    reg [2:0]  s_ar_prot_reg;

    // Response tracking
    reg        s_resp_pending;
    reg [1:0]  s_resp_data_reg;
    reg        s_resp_is_write; // 1 = write response (bresp), 0 = read response (rresp)
    reg [DATA_WIDTH-1:0] s_resp_rdata_reg;

    // State machine for S-domain
    // We need to handle:
    // 1. Accept AW, W, AR from slave
    // 2. Send requests to M-domain via handshake
    // 3. Receive responses from M-domain via handshake
    // 4. Return responses to slave

    // For simplicity, we'll use a simple approach:
    // - AW and W are accepted independently, but we need to pair them for a write
    // - AR is accepted independently for a read
    // - We'll use a small state machine to manage the flow

    // Let's use a simpler approach:
    // - Accept AW and store it
    // - Accept W and store it
    // - When both AW and W are available, send a write request
    // - Accept AR and send a read request
    // - When a response comes back, return it

    // Write address acceptance
    assign s_axil_awready = ~s_aw_pending && ~s_resp_pending;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_aw_pending <= 1'b0;
            s_aw_addr_reg <= {ADDR_WIDTH{1'b0}};
            s_aw_prot_reg <= 3'b000;
        end else if (s_axil_awvalid && s_axil_awready) begin
            s_aw_pending <= 1'b1;
            s_aw_addr_reg <= s_axil_awaddr;
            s_aw_prot_reg <= s_axil_awprot;
        end else if (s_aw_pending && req_synced) begin
            // Request was sent, clear pending
            s_aw_pending <= 1'b0;
        end
    end

    // Write data acceptance
    assign s_axil_wready = ~s_w_pending && ~s_resp_pending;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_w_pending <= 1'b0;
            s_w_data_reg <= {DATA_WIDTH{1'b0}};
            s_w_strb_reg <= {STRB_WIDTH{1'b0}};
        end else if (s_axil_wvalid && s_axil_wready) begin
            s_w_pending <= 1'b1;
            s_w_data_reg <= s_axil_wdata;
            s_w_strb_reg <= s_axil_wstrb;
        end else if (s_w_pending && req_synced) begin
            // Request was sent, clear pending
            s_w_pending <= 1'b0;
        end
    end

    // Read address acceptance
    assign s_axil_arready = ~s_ar_pending && ~s_resp_pending;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_ar_pending <= 1'b0;
            s_ar_addr_reg <= {ADDR_WIDTH{1'b0}};
            s_ar_prot_reg <= 3'b000;
        end else if (s_axil_arvalid && s_axil_arready) begin
            s_ar_pending <= 1'b1;
            s_ar_addr_reg <= s_axil_araddr;
            s_ar_prot_reg <= s_axil_arprot;
        end else if (s_ar_pending && req_synced) begin
            // Request was sent, clear pending
            s_ar_pending <= 1'b0;
        end
    end

    // Response output
    assign s_axil_bvalid = s_resp_pending && s_resp_is_write;
    assign s_axil_bresp  = s_resp_data_reg;
    assign s_axil_rvalid = s_resp_pending && ~s_resp_is_write;
    assign s_axil_rresp  = s_resp_data_reg;
    assign s_axil_rdata  = s_resp_rdata_reg;

    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            s_resp_pending <= 1'b0;
            s_resp_data_reg <= 2'b00;
            s_resp_is_write <= 1'b0;
            s_resp_rdata_reg <= {DATA_WIDTH{1'b0}};
        end else if (resp_synced) begin
            // Response received from M-domain
            s_resp_pending <= 1'b1;
        end else if (s_resp_pending && ((s_resp_is_write && s_axil_bready) || (~s_resp_is_write && s_axil_rready))) begin
            // Response accepted by slave
            s_resp_pending <= 1'b0;
        end
    end

