    reg        m_req_is_write;
    reg [ADDR_WIDTH-1:0] m_req_addr_reg;
    reg [2:0]  m_req_prot_reg;
    reg [DATA_WIDTH-1:0] m_req_data_reg;
    reg [STRB_WIDTH-1:0] m_req_strb_reg;

    // Response tracking
    reg        m_resp_pending;
    reg [1:0]  m_resp_data_reg;
    reg        m_resp_is_write;
    reg [DATA_WIDTH-1:0] m_resp_rdata_reg;

    // State machine for M-domain
    // States:
    // 0: IDLE - waiting for request from S-domain
    // 1: AW_WAIT - waiting for AW handshake
    // 2: W_WAIT - waiting for W handshake
    // 3: B_WAIT - waiting for B response
    // 4: AR_WAIT - waiting for AR handshake
    // 5: R_WAIT - waiting for R response

    localparam [2:0] ST_IDLE    = 3'd0;
    localparam [2:0] ST_AW_WAIT = 3'd1;
    localparam [2:0] ST_W_WAIT  = 3'd2;
    localparam [2:0] ST_B_WAIT  = 3'd3;
    localparam [2:0] ST_AR_WAIT = 3'd4;
    localparam [2:0] ST_R_WAIT  = 3'd5;

    reg [2:0] m_state;

    // Master interface outputs
    assign m_axil_awaddr  = m_req_addr_reg;
    assign m_axil_awprot  = m_req_prot_reg;
    assign m_axil_awvalid = (m_state == ST_AW_WAIT);
    assign m_axil_wdata   = m_req_data_reg;
    assign m_axil_wstrb   = m_req_strb_reg;
    assign m_axil_wvalid  = (m_state == ST_W_WAIT);
    assign m_axil_bready  = (m_state == ST_B_WAIT);
    assign m_axil_araddr  = m_req_addr_reg;
    assign m_axil_arprot  = m_req_prot_reg;
    assign m_axil_arvalid = (m_state == ST_AR_WAIT);
    assign m_axil_rready  = (m_state == ST_R_WAIT);

    always @(posedge m_clk or posedge m_rst) begin
