            m_state <= ST_IDLE;
            m_req_pending <= 1'b0;
            m_req_is_write <= 1'b0;
            m_req_addr_reg <= {ADDR_WIDTH{1'b0}};
            m_req_prot_reg <= 3'b000;
            m_req_data_reg <= {DATA_WIDTH{1'b0}};
            m_req_strb_reg <= {STRB_WIDTH{1'b0}};
            m_resp_pending <= 1'b0;
            m_resp_data_reg <= 2'b00;
            m_resp_is_write <= 1'b0;
            m_resp_rdata_reg <= {DATA_WIDTH{1'b0}};
        end else begin
            case (m_state)
                ST_IDLE: begin
                    if (req_synced) begin
                        // Request from S-domain
                        m_req_pending <= 1'b1;
                        if (m_req_is_write) begin
                            m_state <= ST_AW_WAIT;
                        end else begin
                            m_state <= ST_AR_WAIT;
                        end
                    end
                end

                ST_AW_WAIT: begin
                    if (m_axil_awready) begin
                        m_state <= ST_W_WAIT;
                    end
                end

                ST_W_WAIT: begin
                    if (m_axil_wready) begin
                        m_state <= ST_B_WAIT;
                    end
                end

                ST_B_WAIT: begin
                    if (m_axil_bvalid) begin
                        m_resp_data_reg <= m_axil_bresp;
                        m_resp_is_write <= 1'b1;
                        m_resp_pending <= 1'b1;
                        m_state <= ST_IDLE;
                    end
                end

                ST_AR_WAIT: begin
                    if (m_axil_arready) begin
                        m_state <= ST_R_WAIT;
                    end
                end

                ST_R_WAIT: begin
                    if (m_axil_rvalid) begin
                        m_resp_data_reg <= m_axil_rresp;
                        m_resp_rdata_reg <= m_axil_rdata;
                        m_resp_is_write <= 1'b0;
                        m_resp_pending <= 1'b1;
                        m_state <= ST_IDLE;
                    end
                end

                default: begin
                    m_state <= ST_IDLE;
                end
            endcase
        end
    end

